import{c as s,Q as t,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_formulaimage_0000002372135864.Dgf_I_SL.png",d="/assets/zh-cn_formulaimage_0000002405659569.Du--OxvL.png",l="/assets/zh-cn_formulaimage_0000002404172833.DpRwR2Us.png",i="/assets/zh-cn_formulaimage_0000002426040106.prYK4TEs.png",o="/assets/zh-cn_formulaimage_0000002370455372.9Ed6b3Nu.png",c="/assets/zh-cn_formulaimage_0000002370616000.DxV0U5bI.png",r="/assets/zh-cn_formulaimage_0000002370590770.D_AFF46Q.png",x=JSON.parse('{"title":"Crd2Idx","description":"","frontmatter":{},"headers":[{"level":1,"title":"Crd2Idx","slug":"crd2idx"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础数据结构/Coordinate/Crd2Idx.md","filePath":"api/SIMD-API/基础数据结构/Coordinate/Crd2Idx.md"}'),h={name:"api/SIMD-API/基础数据结构/Coordinate/Crd2Idx.md"};function u(C,a,S,g,b,m){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="crd2idx" tabindex="-1">Crd2Idx <a class="header-anchor" href="#crd2idx" aria-label="Permalink to &quot;Crd2Idx&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Crd2Idx函数用于将多维坐标（Coordinate）通过布局（Layout）转换为内存位置索引（Index），这里的Layout包含了Shape和Stride信息。</p><p>对于一个布局Layout，其Shape为(d0, d1, ..., dn)，Stride为(s0, s1, ..., sn)，Coordinate为(c0, c1, ..., cn)到线性索引Index的转换公式为：</p><p><img src="'+p+`" alt=""></p><p>例如，对于Shape (3, 4, 5)，Stride (20, 5, 1)和Coordinate (1, 2, 3)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>维度0: c₀ * s₀ = 1 * 20 = 20 </span></span>
<span class="line"><span>维度1: c₁ * s₁ = 2 * 5  = 10 </span></span>
<span class="line"><span>维度2: c₂ * s₂ = 3 * 1  = 3</span></span>
<span class="line"><span>Index = 20 + 10 + 3 = 33</span></span></code></pre></div><p>当Coordinate维度和Stride维度不相同时，可以采用去线性化（delinearize）的方法，使得Coordinate维度和Stride维度相同，再使用上述公式计算得到最终结果。</p><p>去线性化的方法介绍如下：对于一个n维数组，形状为(d0, d1, ..., dn)，线性坐标c对应的多维坐标(c0, c1, ..., cn)，可以通过以下公式进行转换：</p><p><img src="`+d+`" alt=""></p><p>例如：对于Shape ((2, 4), (3, 5))，Stride((3, 6), (1, 24))，Layout ((2, 4), (3, 5)) : ((3, 6), (1, 24))，Coordinate（11, 12），按照列优先原则，Crd2Idx的结果为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>crd2idx = delinearize(11, 12) * stride </span></span>
<span class="line"><span>= ((11 % 2, 11 / 2), (12 % 3, 12 / 3)) *  ((3, 6), (1, 24))</span></span>
<span class="line"><span>= ((1, 5), (0, 4)) *  ((3, 6), (1, 24))</span></span>
<span class="line"><span>= 1 * 3 + 5 * 6 + 0 * 1 + 4 * 24 </span></span>
<span class="line"><span>= 129</span></span></code></pre></div><p>总结上述过程，计算公式如下：</p><p><img src="`+l+'" alt=""></p><p><img src="'+i+'" alt=""></p><p><img src="'+o+'" alt=""></p><p><img src="'+c+'" alt=""></p><p>其中(d0, d1, ..., dn)为Shape，(s0, s1, ..., sn)为Stride，delinearize公式展开如下：</p><p><img src="'+r+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Layout输入，Coordinate转换为Index</span></span>
<span class="line"><span>template &lt;typename CoordType, typename ShapeType, typename StrideType&gt;</span></span>
<span class="line"><span>__aicore__ inline constexpr auto Crd2Idx(const CoordType&amp; coord, const Layout&lt;ShapeType, StrideType&gt;&amp; layout)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Shape和Stride输入，Coordinate转换为Index</span></span>
<span class="line"><span>template &lt;typename CoordType, typename ShapeType, typename StrideType&gt;</span></span>
<span class="line"><span>__aicore__ inline constexpr auto Crd2Idx(const CoordType&amp; coord, const ShapeType&amp; shape, const StrideType&amp; stride)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>coord</td><td>输入</td><td>Std::tuple结构类型，用于表示张量在不同维度上的坐标值。 输入的数据类型支持size_t和Std::Int。</td></tr><tr><td>layout</td><td>输入</td><td>输入的Layout对象。 输入的数据类型支持size_t和Std::Int。</td></tr><tr><td>shape</td><td>输入</td><td>Std::tuple结构类型，用于定义数据的逻辑形状，例如二维矩阵的行数和列数或多维张量的各维度大小。 输入的数据类型支持size_t和Std::Int。</td></tr><tr><td>stride</td><td>输入</td><td>Std::tuple结构类型，用于定义各维度在内存中的步长，即同维度相邻元素在内存中的间隔，间隔的单位为元素，与Shape的维度信息一一对应。 输入的数据类型支持size_t和Std::Int。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>返回根据Coordinate信息转换之后的索引值。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>输入参数需满足对应的数据类型要求。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Layout形式入参计算索引值</span></span>
<span class="line"><span>constexpr int M = 11;</span></span>
<span class="line"><span>constexpr int N = 12;</span></span>
<span class="line"><span>constexpr int blockM = 13;</span></span>
<span class="line"><span>constexpr int blockN = 14;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auto coord = AscendC::MakeCoord(AscendC::Std::Int&lt;20&gt;{}, AscendC::Std::Int&lt;30&gt;{});</span></span>
<span class="line"><span>auto shape = AscendC::MakeShape(AscendC::MakeShape(AscendC::Std::Int&lt;blockM&gt;{}, AscendC::Std::Int&lt;M/blockM&gt;{}), AscendC::MakeShape(AscendC::Std::Int&lt;blockN&gt;{}, AscendC::Std::Int&lt;N/blockN&gt;{}));</span></span>
<span class="line"><span>auto stride = AscendC::MakeStride(AscendC::MakeStride(AscendC::Std::Int&lt;blockN&gt;{}, AscendC::Std::Int&lt;blockM*blockN&gt;{}),AscendC::MakeStride(AscendC::Std::Int&lt;1&gt;{}, AscendC::Std::Int&lt;M*blockN&gt;{}));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auto layout = AscendC::MakeLayout(shape, stride);</span></span>
<span class="line"><span>auto index = layout(coord); // decltype(index)::value = 590</span></span>
<span class="line"><span>index = AscendC::Crd2Idx(coord, layout);  // decltype(index)::value = 590</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Shape和Stride形式入参计算索引值</span></span>
<span class="line"><span>auto blockCoordM    = AscendC::Std::Int&lt;11&gt;{};</span></span>
<span class="line"><span>auto blockCoordN    = AscendC::Std::Int&lt;12&gt;{};</span></span>
<span class="line"><span>auto baseShapeM     = AscendC::Std::Int&lt;13&gt;{};</span></span>
<span class="line"><span>auto baseShapeN     = AscendC::Std::Int&lt;14&gt;{};</span></span>
<span class="line"><span>auto basestrideM    = AscendC::Std::Int&lt;15&gt;{};</span></span>
<span class="line"><span>auto basestrideN    = AscendC::Std::Int&lt;16&gt;{};</span></span>
<span class="line"><span>auto coord = AscendC::MakeCoord(AscendC::Std::Int&lt;0&gt;{}, blockCoordN);</span></span>
<span class="line"><span>auto shape = AscendC::MakeShape(AscendC::MakeShape(baseShapeM, baseShapeM), AscendC::MakeShape(baseShapeN, baseShapeN));</span></span>
<span class="line"><span>auto stride = AscendC::MakeStride(AscendC::MakeStride(basestrideM, basestrideM),AscendC::MakeStride(basestrideN, basestrideN));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auto index = AscendC::Crd2Idx(coord, shape, stride); // decltype(index)::value = 192</span></span></code></pre></div>`,31)])])}const A=s(h,[["render",u]]);export{x as __pageData,A as default};
